      { id: "item-2", kind: "hunk" as const, filePath: "src/a.ts", oldPath: null, status: "modified" as const, ordinal: 1, oldStart: 5, oldLines: 1, newStart: 5, newLines: 1, patch: "patch", contentHash: "h2" },
    ],
  }],
