   295	      published_at TEXT,
   296	      archived_at TEXT,
   297	      file_count INTEGER NOT NULL,
   298	      item_count INTEGER NOT NULL,
   299	      chapter_count INTEGER NOT NULL DEFAULT 0,
   300	      manifest_path TEXT NOT NULL,
   301	      review_path TEXT
   302	    );
   303	    CREATE INDEX IF NOT EXISTS runs_root_created ON runs(root_path, created_at DESC);
   304	
   305	    CREATE TABLE IF NOT EXISTS items (
   306	      item_id TEXT NOT NULL,
   307	      run_id TEXT NOT NULL REFERENCES runs(run_id) ON DELETE CASCADE,
   308	      file_id TEXT NOT NULL,
   309	      file_path TEXT NOT NULL,
   310	      ordinal INTEGER NOT NULL,
   311	      kind TEXT NOT NULL,
   312	      PRIMARY KEY (run_id, item_id)
   313	    );
   314	  `);
   315	  const columns = database.prepare("PRAGMA table_info(runs)").all() as Array<{ name: string }>;
   316	  if (!columns.some((column) => column.name === "archived_at")) {
