   337	async function captureRepositorySnapshot(
   338	  repositoryRoot: string,
   339	  ref: string,
   340	  maxFiles: number,
   341	): Promise<CapturedReview> {
   342	  const sha = await gitText(repositoryRoot, ["rev-parse", ref]);
   343	  const allPaths = splitNull(await gitBuffer(repositoryRoot, ["ls-tree", "-r", "--name-only", "-z", sha]));
   344	  const files: CapturedFile[] = [];
   345	  const skipped: Array<{ filePath: string; reason: string }> = [];
   346	  let totalBytes = 0;
   347	
   348	  for (const filePath of allPaths) {
   349	    if (files.length >= maxFiles) {
   350	      skipped.push({ filePath, reason: `repository file limit ${maxFiles} reached` });
   351	      continue;
   352	    }
   353	    if (isGeneratedOrVendorPath(filePath)) {
   354	      skipped.push({ filePath, reason: "generated, vendored, or lock file" });
   355	      continue;
   356	    }
   357	    const content = await readGitObject(repositoryRoot, sha, filePath);
   358	    if (content === null) {
   359	      skipped.push({ filePath, reason: "could not read Git object" });
   360	      continue;
   361	    }
   362	    if (content.length > MAX_FILE_SIZE) {
   363	      skipped.push({ filePath, reason: `file exceeds ${MAX_FILE_SIZE} bytes` });
   364	      continue;
   365	    }
   366	    if (totalBytes + content.length > MAX_REPOSITORY_BYTES) {
   367	      skipped.push({ filePath, reason: `repository content limit ${MAX_REPOSITORY_BYTES} bytes reached` });
   368	      continue;
   369	    }
   370	    if (isBinary(content)) {
   371	      skipped.push({ filePath, reason: "binary file" });
   372	      continue;
   373	    }
   374	    totalBytes += content.length;
   375	    const source = content.toString("utf8");
   376	    const previewLines = source.split("\n").slice(0, 240);
   377	    const truncated = source.split("\n").length > previewLines.length;
   378	    const patch = [
   379	      ...previewLines.map((line, index) => `${String(index + 1).padStart(5)} | ${line}`),
   380	      ...(truncated ? ["[file preview truncated; inspect the repository for the full source]"] : []),
   381	    ].join("\n");
   382	    const itemId = stableId("item", sha, filePath, sha256(content));
   383	    files.push({
   384	      id: stableId("file", sha, filePath),
   385	      filePath,
   386	      oldPath: null,
   387	      status: "snapshot",
   388	      beforeContent: null,
   389	      afterContent: content,
   390	      additions: 0,
   391	      deletions: 0,
   392	      language: languageForPath(filePath),
   393	      size: content.length,
   394	      items: [{
   395	        id: itemId,
   396	        kind: "file",
   397	        filePath,
   398	        oldPath: null,
   399	        status: "snapshot",
   400	        ordinal: 0,
   401	        oldStart: null,
   402	        oldLines: null,
   403	        newStart: 1,
   404	        newLines: source === "" ? 0 : source.split("\n").length,
   405	        patch,
   406	        contentHash: sha256(content),
   407	      }],
   408	    });
   409	  }
   410	
   411	  if (files.length === 0) throw new Error("The repository snapshot contains no reviewable text files.");
