   413	  return await buildCapturedReview(repositoryRoot, scope, files, skipped);
   414	}
   415	
   416	function isGeneratedOrVendorPath(filePath: string): boolean {
   417	  const path = `/${filePath.toLowerCase()}/`;
   418	  if (["/node_modules/", "/vendor/", "/dist/", "/build/", "/.next/", "/.turbo/", "/coverage/"].some((part) => path.includes(part))) {
   419	    return true;
   420	  }
   421	  return /(^|\/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?|cargo\.lock|composer\.lock)$/.test(filePath.toLowerCase());
   422	}
   423	
   424	async function buildCapturedReview(
   425	  repositoryRoot: string,
   426	  scope: ReviewScope,
   427	  files: CapturedFile[],
   428	  skipped: Array<{ filePath: string; reason: string }>,
   429	): Promise<CapturedReview> {
   430	  return {
   431	    repositoryId: stableId("repo", repositoryRoot),
   432	    repositoryRoot,
   433	    repositoryName: basename(repositoryRoot),
   434	    scope,
   435	    files,
   436	    skipped,
   437	  };
   438	}

