     1	import { spawn } from "node:child_process";
     2	
     3	export interface ProcessResult {
     4	  stdout: Buffer;
     5	  stderr: Buffer;
     6	  exitCode: number;
     7	}
     8	
     9	export async function runProcess(
    10	  command: string,
    11	  args: string[],
    12	  cwd: string,
    13	  acceptedExitCodes: number[] = [0],
    14	): Promise<ProcessResult> {
    15	  return await new Promise((resolve, reject) => {
    16	    const child = spawn(command, args, {
    17	      cwd,
    18	      env: { ...process.env, GIT_OPTIONAL_LOCKS: "0" },
    19	      stdio: ["ignore", "pipe", "pipe"],
    20	    });
    21	    const stdout: Buffer[] = [];
    22	    const stderr: Buffer[] = [];
    23	    child.stdout.on("data", (chunk: Buffer) => stdout.push(chunk));
    24	    child.stderr.on("data", (chunk: Buffer) => stderr.push(chunk));
    25	    child.on("error", reject);
    26	    child.on("close", (exitCode) => {
    27	      const result = {
    28	        stdout: Buffer.concat(stdout),
    29	        stderr: Buffer.concat(stderr),
    30	        exitCode: exitCode ?? -1,
    31	      };
    32	      if (!acceptedExitCodes.includes(result.exitCode)) {
    33	        reject(new Error(
    34	          `${command} ${args.join(" ")} failed (${result.exitCode}): ${result.stderr.toString("utf8").trim()}`,
    35	        ));
    36	        return;
    37	      }
    38	      resolve(result);
    39	    });
    40	  });
    41	}
    42	
    43	export async function gitBuffer(
    44	  cwd: string,
    45	  args: string[],
    46	  acceptedExitCodes: number[] = [0],
    47	): Promise<Buffer> {
    48	  return (await runProcess("git", args, cwd, acceptedExitCodes)).stdout;
    49	}
    50	
    51	export async function gitText(
    52	  cwd: string,
    53	  args: string[],
    54	  acceptedExitCodes: number[] = [0],
    55	): Promise<string> {
    56	  return (await gitBuffer(cwd, args, acceptedExitCodes)).toString("utf8").trim();
    57	}
