   290	      filePath: changedPath.filePath,
   291	      oldPath: changedPath.oldPath,
   292	      status: changedPath.status,
   293	      ordinal,
   294	      oldStart,
   295	      oldLines,
   296	      newStart,
   297	      newLines,
   298	      patch: hunkPatch,
   299	      contentHash: sha256(hunkPatch),
   300	    });
   301	  };
   302	
   303	  for (const line of lines) {
   304	    const match = line.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
   305	    if (match) {
   306	      flush();
   307	      coordinates = match;
   308	      current = [line];
   309	    } else if (current) {
