 41	// Deliberately a textual classifier, not a claim about module resolution or runtime behavior.
 42	// Only complete, single-line static imports/re-exports with unchanged syntax qualify.
 43	function importLine(line: string): { source: string; shape: string } | null {
 44	  const match = /^(\s*(?:import\s+(?:type\s+)?[\w$*{},\s]+\s+from\s*|export\s+(?:type\s+)?(?:\*|\{[\w$,\s]*\})\s+from\s*|import\s*))(["'])([^"'\\\r\n]+)\2(\s*;?\s*)$/.exec(line);
 45	  if (!match) return null;
 46	  return { source: match[3]!, shape: `${match[1]}${match[2]}SOURCE${match[2]}${match[4]}` };
 47	}
 48	
 49	export function importRewrite(item: ReviewItem): Transformation["mappings"] | null {
 50	  if (item.kind !== "hunk" || !["modified", "renamed"].includes(item.status)) return null;
 51	  const mappings = new Map<string, { before: string; after: string }>();
 52	  let removed: string[] = [];
 53	  let added: string[] = [];
 54	  let valid = true;
 55	  const flush = (): void => {
 56	    if (removed.length !== added.length) valid = false;
 57	    for (let i = 0; i < removed.length; i += 1) {
 58	      const before = importLine(removed[i]!);
 59	      const after = importLine(added[i] ?? "");
 60	      if (!before || !after || before.shape !== after.shape || before.source === after.source) {
 61	        valid = false;
 62	      } else {
 63	        const mapping = { before: before.source, after: after.source };
 64	        mappings.set(JSON.stringify(mapping), mapping);
 65	      }
 66	    }
 67	    removed = [];
 68	    added = [];
 69	  };
 70	  for (const line of item.patch.split("\n")) {
 71	    if (line.startsWith("@@") || line.startsWith("\\")) { flush(); continue; }
 72	    if (line.startsWith("-")) removed.push(line.slice(1));
 73	    else if (line.startsWith("+")) added.push(line.slice(1));
 74	    else flush();
 75	  }
 76	  flush();
 77	  return valid && mappings.size > 0
 78	    ? [...mappings.values()].sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)))
 79	    : null;
 80	}
