  3	export function chapterLabels(chapters: Chapter[]): Map<string, string> {
  4	  const labels = new Map<string, string>();
  5	  const children = new Map<string | null, Chapter[]>();
  6	  for (const chapter of chapters) {
  7	    const siblings = children.get(chapter.parentId) ?? [];
  8	    siblings.push(chapter);
  9	    children.set(chapter.parentId, siblings);
 10	  }
 11	  for (const siblings of children.values()) siblings.sort((a, b) => a.order - b.order);
 12	
 13	  const visit = (parentId: string | null, depth: number): void => {
 14	    for (const [index, chapter] of (children.get(parentId) ?? []).entries()) {
 15	      labels.set(chapter.id, depth === 0 ? String(index + 1) : alphabetic(index));
 16	      visit(chapter.id, depth + 1);
 17	    }
 18	  };
 19	  visit(null, 0);
 20	  return labels;
 21	}
 22	
 23	export function chapterItemRefs(chapters: Chapter[], chapterId: string): string[] {
 24	  const byParent = new Map<string, Chapter[]>();
 25	  for (const chapter of chapters) {
 26	    if (chapter.parentId === null) continue;
 27	    const children = byParent.get(chapter.parentId) ?? [];
 28	    children.push(chapter);
 29	    byParent.set(chapter.parentId, children);
 30	  }
 31	  const byId = new Map(chapters.map((chapter) => [chapter.id, chapter] as const));
 32	  const refs: string[] = [];
 33	  const visited = new Set<string>();
 34	  const visit = (id: string): void => {
 35	    if (visited.has(id)) return;
 36	    visited.add(id);
 37	    const chapter = byId.get(id);
 38	    if (!chapter) return;
 39	    refs.push(...chapter.itemRefs);
 40	    for (const child of byParent.get(id) ?? []) visit(child.id);
 41	  };
 42	  visit(chapterId);
 43	  return refs;
 44	}
 45	
 46	export function childChapters(chapters: Chapter[], chapterId: string): Chapter[] {
 47	  return chapters
 48	    .filter((chapter) => chapter.parentId === chapterId)
 49	    .slice()
 50	    .sort((a, b) => a.order - b.order);
 51	}
