 41	// Deliberately a textual classifier, not a claim about module resolution or runtime behavior.
 42	// Only complete, single-line static imports/re-exports with unchanged syntax qualify.
 43	function importLine(line: string): { source: string; shape: string } | null {
 44	  const match = /^(\s*(?:import\s+(?:type\s+)?[\w$*{},\s]+\s+from\s*|export\s+(?:type\s+)?(?:\*|\{[\w$,\s]*\})\s+from\s*|import\s*))(["'])([^"'\\\r\n]+)\2(\s*;?\s*)$/.exec(line);
 45	  if (!match) return null;
 46	  return { source: match[3]!, shape: `${match[1]}${match[2]}SOURCE${match[2]}${match[4]}` };
 47	}
 48	
 49	export function importRewrite(item: ReviewItem): Transformation["mappings"] | null {
 50	  if (item.kind !== "hunk" || !["modified", "renamed"].includes(item.status)) return null;
 51	  const mappings = new Map<string, { before: string; after: string }>();
 52	  let removed: string[] = [];
 53	  let added: string[] = [];
 54	  let valid = true;
 55	  const flush = (): void => {
 56	    if (removed.length !== added.length) valid = false;
 57	    for (let i = 0; i < removed.length; i += 1) {
 58	      const before = importLine(removed[i]!);
 59	      const after = importLine(added[i] ?? "");
 60	      if (!before || !after || before.shape !== after.shape || before.source === after.source) {
 61	        valid = false;
 62	      } else {
 63	        const mapping = { before: before.source, after: after.source };
 64	        mappings.set(JSON.stringify(mapping), mapping);
 65	      }
 66	    }
 67	    removed = [];
 68	    added = [];
 69	  };
 70	  for (const line of item.patch.split("\n")) {
 71	    if (line.startsWith("@@") || line.startsWith("\\")) { flush(); continue; }
 72	    if (line.startsWith("-")) removed.push(line.slice(1));
 73	    else if (line.startsWith("+")) added.push(line.slice(1));
 74	    else flush();
 75	  }
 76	  flush();
 77	  return valid && mappings.size > 0
 78	    ? [...mappings.values()].sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)))
 79	    : null;
 80	}
 81	
 82	export function isExactMove(file: ReviewFile): boolean {
 83	  return file.status === "renamed" && !!file.oldPath && file.oldPath !== file.filePath
 84	    && file.beforeBlob !== null && file.beforeBlob === file.afterBlob;
 85	}
 86	
 87	/** Infer a segment-aligned prefix rule; every concrete suffix must remain identical. */
 88	export function prefixRewrite(mapping: { before: string; after: string }): Transformation["mappings"][number] | null {
 89	  const before = mapping.before.split("/");
 90	  const after = mapping.after.split("/");
 91	  let common = 0;
 92	  while (common < Math.min(before.length, after.length) - 1
 93	    && before[before.length - common - 1] === after[after.length - common - 1]) common += 1;
 94	  if (common === 0) return null;
 95	  const from = `${before.slice(0, -common).join("/")}/`;
 96	  const to = `${after.slice(0, -common).join("/")}/`;
 97	  // Literal wildcard paths and dot-segment paths do not support an unambiguous rule.
 98	  if (from === to || [...before, ...after].some((part) => !part || part === "." || part === ".." || part.includes("*"))) return null;
 99	  return { before: from, after: to, prefix: true };
100	}
101	
102	export function matchesRewrite(mapping: { before: string; after: string }, rule: Transformation["mappings"][number]): boolean {
103	  return rule.prefix
104	    ? mapping.before.startsWith(rule.before) && mapping.before.length > rule.before.length
105	      && mapping.after === rule.after + mapping.before.slice(rule.before.length)
106	    : mapping.before === rule.before && mapping.after === rule.after;
107	}
108	
109	export function moveDescription(file: ReviewFile): string {
110	  if (isExactMove(file)) return "Identical content";
111	  return file.items.length > 0 && file.items.every((item) => importRewrite(item) !== null)
112	    ? "Moved + import rewrite" : "Moved and edited";
113	}
114	
115	export function partitionChanges(matches: ItemMatch[]): { transformations: Transformation[]; individual: ItemMatch[] } {
116	  const candidates = new Map<string, Transformation>();
117	  const unique = [...new Map(matches.map((match) => [match.item.id, match])).values()];
118	  const rewrites = new Map(unique.map(({ item }) => [item.id, importRewrite(item)]));
119	  const prefixes = new Map<string, { rule: Transformation["mappings"][number]; sources: Set<string>; files: Set<string> }>();
120	  for (const { file, item } of unique) {
121	    for (const mapping of rewrites.get(item.id) ?? []) {
122	      const rule = prefixRewrite(mapping);
123	      if (!rule) continue;
124	      const key = JSON.stringify(rule);
125	      const entry = prefixes.get(key) ?? { rule, sources: new Set<string>(), files: new Set<string>() };
126	      entry.sources.add(mapping.before);
127	      entry.files.add(file.id);
128	      prefixes.set(key, entry);
129	    }
130	  }
131	  // A repeated edit of one module is an exact mapping, not evidence of a prefix migration.
132	  const supported = new Set([...prefixes].filter(([, entry]) => entry.sources.size >= 2 && entry.files.size >= 2).map(([key]) => key));
133	  for (const match of unique) {
134	    const move = isExactMove(match.file);
135	    const concrete = move ? [] : rewrites.get(match.item.id);
136	    if (concrete == null) continue;
137	    const rules = concrete.map((mapping) => {
138	      const prefix = prefixRewrite(mapping);
139	      return prefix && supported.has(JSON.stringify(prefix)) && matchesRewrite(mapping, prefix) ? prefix : mapping;
140	    });
141	    const mappings = [...new Map(rules.map((rule) => [JSON.stringify(rule), rule])).values()]
142	      .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));
143	    const key = move ? "exact-moves" : JSON.stringify(mappings);
144	    const group = candidates.get(key) ?? { key, kind: move ? "moves" : "imports", mappings, matches: [] };
145	    group.matches.push(match);
146	    candidates.set(key, group);
147	  }
148	  const transformations = [...candidates.values()].filter((group) => new Set(group.matches.map(({ file }) => file.id)).size >= 2);
149	  const grouped = new Set(transformations.flatMap((group) => group.matches.map(({ item }) => item.id)));
150	  return { transformations, individual: unique.filter(({ item }) => !grouped.has(item.id)) };
151	}
