  4	export interface ItemMatch { file: ReviewFile; item: ReviewItem }
  5	export interface FileGroup {
  6	  file: ReviewFile;
  7	  items: ReviewItem[];
  8	  additions: number;
  9	  deletions: number;
 10	}
 11	export interface Transformation {
 12	  key: string;
 13	  kind: "imports" | "moves";
 14	  mappings: Array<{ before: string; after: string; prefix?: boolean }>;
 15	  matches: ItemMatch[];
 16	}
