 36	export function otherFileChapters(file: ReviewFile, chapters: Chapter[], currentId?: string): Chapter[] {
 37	  const refs = new Set(file.items.map((item) => item.id));
 38	  return chapters.filter((chapter) => chapter.id !== currentId && chapter.itemRefs.some((ref) => refs.has(ref)));
 39	}
